source_context:
 1: ---
 2: - hosts: "{{ openshift_node | default('masters') }}"
 3:   gather_facts: "{{ gathering_host_info | default('true') | bool == true }}"
 4: 
 5:   environment:
 6:     KUBECONFIG: /etc/kubernetes/admin.conf
 7: 
 8:   # Define default values for variables that are common between roles
 9:   vars:
10:     openshift_admin_user: admin
11:     openshift_admin_pwd: ''
12:     client_tool: oc
13: 
14:   roles:
15:     - { role: 'persistence',            tags: 'persistence'}          # When Minishift or oc cluster up is NOT used
16:     - { role: 'identity_provider',      tags: 'identity_provider'}    # Use HTPasswdPasswordIdentityProvider as Identity Provider -> more secure
17:     - { role: 'enable_cluster_role',    tags: 'enable_cluster_role'}
18:     - { role: 'add_extra_users',        tags: 'add_extra_users'}
19:     - { role: 'delete_extra_users',     tags: 'delete_extra_users'}
20:     - { role: 'install_oc',             tags: 'install_oc'}           # Install oc client when cluster role is not used
21:     - { role: 'docker',                 tags: 'docker'}               # Enable to access docker on port 2376
22:     - { role: 'create_projects',        tags: 'create_projects'}
23:     - { role: 'install_nexus',          tags: 'nexus'}
24:     - { role: 'install_jenkins',        tags: 'jenkins'}
25:     - { role: 'install_jaeger',         tags: 'jaeger'}
26:     - { role: 'install_istio',          tags: 'istio'}
27:     - { role: 'install_launcher',       tags: 'install-launcher'}
28:     - { role: 'uninstall_launcher',     tags: 'uninstall-launcher'}
29:     - { role: 'component_crd_operator', tags: 'component_crd_operator'}
30:     - { role: 'snowdrop_site',          tags: 'snowdrop-site'}
31:     - { role: 'tekton_pipelines',       tags: 'tekton_pipelines'}
32:     - { role: 'halkyon',                tags: 'halkyon'}
33:     - { role: 'k8s_cluster',            tags: 'k8s_cluster'}
34:     - { role: 'k8s_config',             tags: 'k8s_config'}
35:     - { role: 'k8s_dashboard',          tags: 'k8s_dashboard'}
36:     - { role: 'k8s_service_broker',     tags: 'k8s_service_broker'}
37:     - { role: 'k8s_halkyon_site',       tags: 'k8s_halkyon_site'}
38:     - { role: 'k8s_issuer_certificate', tags: 'k8s_issuer_certificate'}
39:     - { role: 'kind',                   tags: 'kind'}
40:     - { role: 'ingress',                tags: 'ingress'}
41:     - { role: 'helm',                   tags: 'helm'}
42:     - { role: 'kubedb',                 tags: 'kubedb'}
43:     - { role: 'docker_registry',        tags: 'docker_registry'}
44:     - { role: 'tekton_pipelines',       tags: 'tekton_pipelines'}
45:     - { role: 'component_crd_operator', tags: 'component_crd_operator'}
46:     - { role: 'ocp4_console',           tags: 'ocp4_console'}
47:     - { role: 'cert_manager',           tags: 'cert_manager'}
